// wasm's GC objects in JavaScript, and casts of the values JavaScript gives.
const W = WebAssembly;
const b = new WasmModuleBuilder();
const st = b.addStruct([makeField(kWasmI32, true)]);
const st2 = b.addStruct([makeField(kWasmI32, true), makeField(kWasmI64, true)], st);
const ar = b.addArray(kWasmI32, true);
b.addFunction("struct", makeSig([], [wasmRefType(st)])).addBody([kExprI32Const, 42, ...GCInstr(kExprStructNew), st]).exportFunc();
b.addFunction("sub", makeSig([], [wasmRefType(st2)])).addBody([kExprI32Const, 1, kExprI64Const, 2, ...GCInstr(kExprStructNew), st2]).exportFunc();
b.addFunction("array", makeSig([], [wasmRefType(ar)])).addBody([kExprI32Const, 5, kExprI32Const, 3, ...GCInstr(kExprArrayNew), ar]).exportFunc();
b.addFunction("get", makeSig([wasmRefNullType(st)], [kWasmI32])).addBody([kExprLocalGet, 0, ...GCInstr(kExprStructGet), st, 0]).exportFunc();
b.addFunction("sub2", makeSig([wasmRefNullType(st2)], [kWasmI32])).addBody([kExprI32Const, 2]).exportFunc();
b.addFunction("len", makeSig([kWasmArrayRef], [kWasmI32])).addBody([kExprLocalGet, 0, ...GCInstr(kExprArrayLen)]).exportFunc();
b.addFunction("id", makeSig([kWasmAnyRef], [kWasmAnyRef])).addBody([kExprLocalGet, 0]).exportFunc();
b.addFunction("ext", makeSig([kWasmExternRef], [kWasmExternRef])).addBody([kExprLocalGet, 0]).exportFunc();
b.addFunction("isI31", makeSig([kWasmExternRef], [kWasmI32])).addBody([kExprLocalGet, 0, ...GCInstr(kExprExternInternalize), ...GCInstr(kExprRefTest), kI31RefCode]).exportFunc();
b.addFunction("isStruct", makeSig([kWasmAnyRef], [kWasmI32])).addBody([kExprLocalGet, 0, ...GCInstr(kExprRefTest), kStructRefCode]).exportFunc();
b.addFunction("structOrNull", makeSig([kWasmStructRef], [kWasmStructRef])).addBody([kExprLocalGet, 0]).exportFunc();
b.addFunction("arrayOrNull", makeSig([kWasmArrayRef], [kWasmArrayRef])).addBody([kExprLocalGet, 0]).exportFunc();
b.addFunction("castStruct", makeSig([kWasmAnyRef], [wasmRefType(st)])).addBody([kExprLocalGet, 0, ...GCInstr(kExprRefCast), st]).exportFunc();
const e = b.instantiate().exports;
const s = e.struct(), a = e.array();
p("typeof", () => [typeof s, typeof a].join());
p("toString", () => [Object.prototype.toString.call(s), Object.prototype.toString.call(a)].join());
p("prototype", () => [Object.getPrototypeOf(s), Object.getPrototypeOf(a)].join());
p("extensible", () => [Object.isExtensible(s), Object.isFrozen(s), Object.isSealed(s)].join());
p("get", () => [s.foo, s[0], a[0], a.length].join());
p("set", () => { s.foo = 1; });
p("strict set", () => { "use strict"; a[0] = 1; });
p("define", () => Object.defineProperty(s, "x", { value: 1 }));
p("delete", () => delete s.x);
p("setPrototypeOf", () => Object.setPrototypeOf(s, {}));
p("Reflect.setPrototypeOf null", () => Reflect.setPrototypeOf(s, null));
p("preventExtensions", () => Object.preventExtensions(a));
p("seal", () => Object.seal(a));
p("freeze", () => Object.freeze(s));
p("keys", () => [Object.keys(s).length, Reflect.ownKeys(a).length, "x" in s].join());
p("method", () => s.toString());
p("same object", () => e.id(s) === s && e.ext(a) === a);
p("back to wasm", () => [e.get(s), e.len(a), e.isStruct(s), e.isStruct(a)].join());
p("subtype", () => [e.get(e.sub()), e.sub2(e.sub())].join());
p("supertype refused", () => e.sub2(s));
p("struct where array", () => e.len(s));
p("struct as structref", () => e.structOrNull(s) === s);
p("array as structref", () => e.structOrNull(a));
p("array as arrayref", () => e.arrayOrNull(a) === a);
p("map key", () => { const m = new Map([[s, 1]]); const w = new WeakMap([[a, 2]]); return [m.get(s), w.get(a)].join(); });
p("i31 through extern", () => [e.isI31(5), e.isI31(2 ** 30), e.isI31(-(2 ** 30)), e.isI31(1.5), e.isI31(-0), e.isI31("5"), e.isI31(null)].join());
p("anyref numbers", () => [e.id(5), e.id(2 ** 40), e.id(1.5), fmt(e.id(-0)), e.id("s"), e.id(null)].map(String).join());
p("cast", () => e.get(e.castStruct(s)));
p("cast fails", () => e.castStruct(a));
p("cast number", () => e.castStruct(5));
p("JSON", () => JSON.stringify([s]));
p("String", () => String(s));
p("plus", () => s + 1);
